def last_Digit_Factorial(n):
    if n <= 1:
        return 1

    # For any number >= 5, the factorial ends in 0 because it includes factors 2 and 5 (and more)
    # So we only need to check for numbers less than 5 manually or use modulo logic.

    fact = 1
    for i in range(2, n + 1):
        fact *= i

    return fact % 10

